from pathlib import Path
import json,hashlib,html,shutil
p=Path(__file__).parent
pack=json.loads((p/'pack.json').read_text());rubric=json.loads((p/'rubric.json').read_text())
# Embed public fixtures and anchors only; provenance and judge outputs stay separate.
rubric_sha=hashlib.sha256((p/'rubric.json').read_bytes()).hexdigest()
payload=json.dumps({'pack':pack,'rubric':rubric},ensure_ascii=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
template='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rundale judge review</title>
<style>body{font:17px/1.5 system-ui;max-width:920px;margin:32px auto;padding:0 20px;background:#faf8f3;color:#242421}h1{font-size:29px}button,select,input,textarea{font:inherit}button{padding:9px 14px;cursor:pointer;border:1px solid #777;border-radius:6px;background:white}button.primary{background:#234e41;color:white}header{border-bottom:1px solid #ccc;padding-bottom:16px}.toolbar{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:20px 0}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:15px/1.55 ui-monospace,monospace;background:#fff;padding:16px;border:1px solid #ddd;border-radius:7px}fieldset{margin:18px 0;padding:16px;border:1px solid #bbb;border-radius:7px}legend{font-weight:650}label.anchor{display:block;padding:9px;margin:4px 0;background:#fff;border-radius:4px}input[type=radio]{margin-right:9px}textarea{box-sizing:border-box;width:100%;min-height:80px;padding:10px}small,.muted{color:#555}#status{font-weight:600}#warn{color:#923d17}details{margin:12px 0}nav{display:flex;justify-content:space-between;margin:25px 0}.done{color:#206149}input[type=text]{max-width:100%;padding:8px;box-sizing:border-box}#privacy{background:#e9efe9;padding:12px;border-radius:6px}</style>
<header><h1>Rundale judge review</h1><p>Rate the response against its context. Model identities, judge scores, and author expectations are hidden. This is rubric development, not a final benchmark.</p><p id="privacy">This file works offline. Ratings stay in this browser and are downloaded as JSON. Nothing is sent to a server.</p><div class="toolbar"><label>Review track <select id="track"><option value="owner">English: dialogue + multiturn (16)</option><option value="irish">Irish + code-switching (8)</option></select></label><label>Reviewer <input id="reviewer" type="text" placeholder="Your name or identifier"></label></div><p><label><input type="checkbox" id="fluency"> I can independently assess Irish grammar, meaning, and naturalness (required for the Irish track).</label></p><p class="muted">Choose “cannot judge” when context or expertise is insufficient. Explain ambiguous tasks or rubric problems in notes. Do not consult other judges or the source ledger before finishing.</p></header>
<div class="toolbar"><span id="status"></span><select id="jump" aria-label="Jump to example"></select><button id="export" class="primary">Download ratings</button></div><p id="warn" role="status"></p><main id="case"></main><nav><button id="previous">Previous</button><button id="next">Next</button></nav>
<script id="data" type="application/json">__PAYLOAD__</script><script>
'use strict';
const data=JSON.parse(document.getElementById('data').textContent);
const items=data.pack.items, rubric=data.rubric;
const storageKey='rundale-judge-review-v3-__HASH__-__RUBRIC_HASH__';
let state={track:'owner',reviewer:'',fluent:false,ratings:{},index:0};
try{const saved=JSON.parse(localStorage.getItem(storageKey)||'null');if(saved)state={...state,...saved};}catch(e){}
const el=id=>document.getElementById(id);
function save(){try{localStorage.setItem(storageKey,JSON.stringify(state));el('warn').textContent='';}catch(e){el('warn').textContent='Browser storage is unavailable. Download ratings before closing.';}}
function selected(){return items.filter(i=>state.track==='irish'?i.category==='gaeilge':i.category!=='gaeilge');}
function dims(i){return rubric.categories[i.category];}
function record(i){if(!state.ratings[i.id])state.ratings[i.id]={axes:{},notes:''};return state.ratings[i.id];}
function complete(i){const r=state.ratings[i.id];return !!r&&Object.keys(dims(i)).every(a=>Object.prototype.hasOwnProperty.call(r.axes,a)&&(r.axes[a]!==null||r.notes.trim()));}
function add(tag,parent,text){const x=document.createElement(tag);if(text!==undefined)x.textContent=text;parent.appendChild(x);return x;}
function render(){const list=selected();state.index=Math.min(Math.max(state.index,0),list.length-1);const item=list[state.index];const r=record(item);el('track').value=state.track;el('reviewer').value=state.reviewer;el('fluency').checked=state.fluent;el('status').textContent=`${list.filter(complete).length}/${list.length} completed`;
const jump=el('jump');jump.replaceChildren();list.forEach((i,n)=>{const o=document.createElement('option');o.value=n;o.textContent=`${n+1}. ${i.id}${complete(i)?' ✓':''}`;jump.appendChild(o);});jump.value=state.index;
const main=el('case');main.replaceChildren();add('h2',main,`${state.index+1}. ${item.id} · ${item.category}`);
if(item.review_context){add('h3',main,'Relevant context (verbatim excerpts)');add('pre',main,item.review_context);}for(const [label,value] of [['Full character and world instructions',item.system],['Full player request / conversation history',item.user]]){if(item.review_context){const detail=add('details',main);add('summary',detail,label+' — expand if needed');add('pre',detail,typeof value==='string'?value:JSON.stringify(value,null,2));}else{add('h3',main,label);add('pre',main,typeof value==='string'?value:JSON.stringify(value,null,2));}}add('h3',main,'Candidate response to rate');add('pre',main,item.response);
if(rubric.instructions)add('p',main,rubric.instructions);
for(const [axis,spec] of Object.entries(dims(item))){const field=add('fieldset',main);add('legend',field,axis.replaceAll('_',' '));add('p',field,spec.description);for(const [score,anchor] of [...Object.entries(spec.anchors),['skip','Cannot judge / not applicable — explain in notes']]){const label=add('label',field);label.className='anchor';const input=document.createElement('input');input.type='radio';input.name=axis;input.value=score;input.checked=score==='skip'?(Object.prototype.hasOwnProperty.call(r.axes,axis)&&r.axes[axis]===null):r.axes[axis]===Number(score);input.addEventListener('change',()=>{r.axes[axis]=score==='skip'?null:Number(score);save();updateProgress();});label.appendChild(input);label.appendChild(document.createTextNode(score==='skip'?anchor:`${score}: ${anchor}`));}}
add('h3',main,'Notes');const notes=add('textarea',main);notes.setAttribute('aria-label','Review notes');notes.placeholder='What supports the rating? Flag ambiguity, missing facts, or uncertain Irish.';notes.value=r.notes;notes.addEventListener('input',()=>{r.notes=notes.value;save();updateProgress();});el('previous').disabled=state.index===0;el('next').disabled=state.index===list.length-1;
}
function updateProgress(){const list=selected();el('status').textContent=`${list.filter(complete).length}/${list.length} completed`;Array.from(el('jump').options).forEach((o,n)=>o.textContent=`${n+1}. ${list[n].id}${complete(list[n])?' ✓':''}`);}
el('track').addEventListener('change',()=>{state.track=el('track').value;state.index=0;save();render();});el('reviewer').addEventListener('input',()=>{state.reviewer=el('reviewer').value;save();});el('fluency').addEventListener('change',()=>{state.fluent=el('fluency').checked;save();});el('jump').addEventListener('change',()=>{state.index=Number(el('jump').value);save();render();});el('previous').addEventListener('click',()=>{state.index--;save();render();window.scrollTo(0,0);});el('next').addEventListener('click',()=>{state.index++;save();render();window.scrollTo(0,0);});
el('export').addEventListener('click',()=>{if(!state.reviewer.trim()){el('warn').textContent='Enter a reviewer identifier before downloading.';return;}if(state.track==='irish'&&!state.fluent){el('warn').textContent='Irish reference ratings require independent fluency. You can leave this track for a fluent reviewer.';return;}const list=selected();const result={schema_version:'human-review-v2',pack_sha256:'__HASH__',rubric_sha256:'__RUBRIC_HASH__',reviewer:state.reviewer.trim(),track:state.track,fluent_irish_attested:state.fluent,exported_at:new Date().toISOString(),completed:list.filter(complete).length,total:list.length,items:list.map(i=>({id:i.id,axes:state.ratings[i.id]?.axes||{},notes:state.ratings[i.id]?.notes||''}))};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(result,null,2)],{type:'application/json'}));a.download=`rundale-review-${state.track}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);el('warn').textContent=result.completed===result.total?'Ratings downloaded.':`Partial ratings downloaded: ${result.completed}/${result.total} completed.`;});render();
</script></html>'''
sha=hashlib.sha256((p/'pack.json').read_bytes()).hexdigest()
(p/'review.html').write_text(template.replace('__PAYLOAD__',payload).replace('__HASH__',sha).replace('__RUBRIC_HASH__',rubric_sha))
manifest={'schema_version':'review-v2','status':'ready for human review; no judge scores for this revision','pack_sha256':sha,'hashes':{n:hashlib.sha256((p/n).read_bytes()).hexdigest() for n in ['pack.json','rubric.json','provenance.json']},'review_counts':{'owner':16,'fluent_irish':8},'reference_labels_completed':0,'holdout':False}
(p/'manifest.json').write_text(json.dumps(manifest,indent=2))
print('Built offline review page',sha)
